INSERT INTO author (id, user_id, real_name, id_card, intro, audit_status, audit_time, create_time) VALUES
(5, 17, '陈望舒', '360101199203154328', '擅长东方玄幻与古典言情，文风热血细腻兼具。', 1, DATE_SUB(NOW(), INTERVAL 20 DAY) + INTERVAL 10 HOUR, DATE_SUB(NOW(), INTERVAL 36 DAY) + INTERVAL 13 HOUR),
(6, 18, '江离', '440101198807126541', '悬疑推理爱好者，专注反转与氛围营造。', 1, DATE_SUB(NOW(), INTERVAL 16 DAY) + INTERVAL 22 HOUR, DATE_SUB(NOW(), INTERVAL 32 DAY) + INTERVAL 13 HOUR),
(7, 19, '李清和', '510101199501238716', '都市与历史题材写手，细节考据控。', 1, DATE_SUB(NOW(), INTERVAL 8 DAY) + INTERVAL 21 HOUR, DATE_SUB(NOW(), INTERVAL 33 DAY) + INTERVAL 18 HOUR);
INSERT INTO book (id, author_id, category_id, title, intro, status, is_recommend, click_count, collect_count, create_time, update_time) VALUES
(10, 5, 1, '九霄神帝', '少年楚渊身负九霄神印，自玄天宗外门崛起，一路逆天改命，终成一代神帝。', 1, 1, 8560, 320, DATE_SUB(NOW(), INTERVAL 15 DAY) + INTERVAL 10 HOUR, DATE_SUB(NOW(), INTERVAL 10 DAY) + INTERVAL 13 HOUR),
(11, 6, 1, '万古第一剑', '剑冢枯骨生新芽，少年持一柄断剑，问剑万古，斩尽诸天。', 2, 0, 4230, 185, DATE_SUB(NOW(), INTERVAL 5 DAY) + INTERVAL 16 HOUR, DATE_SUB(NOW(), INTERVAL 11 DAY) + INTERVAL 19 HOUR),
(12, 3, 1, '荒天记', '荒域大泽，少年叶荒自蛮荒深处走出，携一株青莲，踏碎荒天。', 1, 0, 5180, 96, DATE_SUB(NOW(), INTERVAL 15 DAY) + INTERVAL 15 HOUR, DATE_SUB(NOW(), INTERVAL 2 DAY) + INTERVAL 20 HOUR),
(13, 7, 2, '重回1998', '一觉醒来，陈默重回1998年。这一次，他要把错过的人、错过的时代，统统握在手里。', 1, 1, 12400, 640, DATE_SUB(NOW(), INTERVAL 33 DAY) + INTERVAL 20 HOUR, DATE_SUB(NOW(), INTERVAL 8 DAY) + INTERVAL 18 HOUR),
(14, 3, 2, '都市之最强狂兵', '五年前，他被逐出家门；五年后，王者归来，搅动一城风云。', 2, 0, 9100, 210, DATE_SUB(NOW(), INTERVAL 26 DAY) + INTERVAL 13 HOUR, DATE_SUB(NOW(), INTERVAL 11 DAY) + INTERVAL 19 HOUR),
(15, 5, 3, '春风不渡', '他是权倾朝野的摄政王，她是寄人篱下的孤女。一纸婚约，将两人的命运绑在一起。', 1, 1, 13800, 980, DATE_SUB(NOW(), INTERVAL 12 DAY) + INTERVAL 15 HOUR, DATE_SUB(NOW(), INTERVAL 2 DAY) + INTERVAL 12 HOUR),
(16, 7, 3, '许你一世长安', '青梅竹马，两小无猜。他说，待我功成名就，许你一世长安。', 2, 0, 7200, 450, DATE_SUB(NOW(), INTERVAL 26 DAY) + INTERVAL 17 HOUR, DATE_SUB(NOW(), INTERVAL 4 DAY) + INTERVAL 22 HOUR),
(17, 6, 3, '山月不知心底事', '小镇书店的老板娘，与归乡的钢琴师，在旧时光里相遇。山月不知心底事，水风空落眼前花。', 1, 0, 6100, 320, DATE_SUB(NOW(), INTERVAL 29 DAY) + INTERVAL 20 HOUR, DATE_SUB(NOW(), INTERVAL 7 DAY) + INTERVAL 20 HOUR),
(18, 6, 4, '雾隐迷城', '一座常年被浓雾笼罩的城市，接连出现离奇失踪案。刑警队长顾砚，一步步逼近迷雾深处的真相。', 1, 0, 8900, 260, DATE_SUB(NOW(), INTERVAL 24 DAY) + INTERVAL 13 HOUR, DATE_SUB(NOW(), INTERVAL 5 DAY) + INTERVAL 21 HOUR),
(19, 5, 4, '第七个目击者', '深夜的便利店，一场抢劫案，七个目击者，却给出了七份完全不同的证词。', 2, 1, 10300, 380, DATE_SUB(NOW(), INTERVAL 17 DAY) + INTERVAL 10 HOUR, DATE_SUB(NOW(), INTERVAL 7 DAY) + INTERVAL 21 HOUR),
(20, 6, 5, '银河猎手', '在星际赏金猎人执照过期的最后一天，老猎人陆遥接下了改变他一生的委托。', 1, 0, 5600, 140, DATE_SUB(NOW(), INTERVAL 38 DAY) + INTERVAL 16 HOUR, DATE_SUB(NOW(), INTERVAL 9 DAY) + INTERVAL 20 HOUR),
(21, 7, 6, '大宋风流', '穿越大宋，且看一个现代灵魂如何在汴京的市井与朝堂之间，活出风流写意的一生。', 1, 1, 9800, 520, DATE_SUB(NOW(), INTERVAL 38 DAY) + INTERVAL 18 HOUR, DATE_SUB(NOW(), INTERVAL 8 DAY) + INTERVAL 11 HOUR),
(22, 5, 6, '汉家儿郎', '犯我强汉者，虽远必诛。一个边关小卒，一步步成长为守护家国的百战将军。', 2, 0, 6600, 240, DATE_SUB(NOW(), INTERVAL 31 DAY) + INTERVAL 9 HOUR, DATE_SUB(NOW(), INTERVAL 12 DAY) + INTERVAL 9 HOUR),
(23, 6, 7, '青云之上', '青云宗外门弟子秦川，偶得上古剑仙传承，自此青云之上，再无对手。', 1, 1, 11200, 470, DATE_SUB(NOW(), INTERVAL 6 DAY) + INTERVAL 11 HOUR, DATE_SUB(NOW(), INTERVAL 11 DAY) + INTERVAL 13 HOUR),
(24, 3, 7, '剑来问道', '一柄凡铁剑，一个拾剑少年。问道之路，始于足下。', 1, 0, 7800, 190, DATE_SUB(NOW(), INTERVAL 7 DAY) + INTERVAL 11 HOUR, DATE_SUB(NOW(), INTERVAL 7 DAY) + INTERVAL 8 HOUR),
(25, 3, 8, '烽火连城', '边城告急，援军断绝。守城将军沈烈，用最后的三千将士，写下烽火中的誓言。', 1, 0, 4700, 130, DATE_SUB(NOW(), INTERVAL 20 DAY) + INTERVAL 9 HOUR, DATE_SUB(NOW(), INTERVAL 3 DAY) + INTERVAL 12 HOUR),
(26, 7, 8, '孤军突击', '敌后孤军，绝境求生。一支特种小队，在敌占区打出了教科书般的穿插突击。', 2, 1, 6900, 280, DATE_SUB(NOW(), INTERVAL 29 DAY) + INTERVAL 16 HOUR, DATE_SUB(NOW(), INTERVAL 11 DAY) + INTERVAL 8 HOUR);
INSERT INTO chapter (id, book_id, title, content, is_free, price, sort, words, read_count, pay_count, create_time, update_time) VALUES
(100, 10, '第1章 废柴觉醒', '推开门的那一刻，少年握紧手中残破的剑，眼中映着满天星斗。这一章《废柴觉醒》，局势悄然生变。少年握紧手中残破的剑，眼中映着满天星斗。强敌环伺，唯有不断破境，方能护住身后之人。灵气复苏之后，这片大陆的格局被彻底改写。灵气复苏之后，这片大陆的格局被彻底改写。书中的主角回望来路，心中百感交集。强敌环伺，唯有不断破境，方能护住身后之人。灵气复苏之后，这片大陆的格局被彻底改写。故事才刚刚开始。', 1, 0, 1, 192, 428, 0, DATE_SUB(NOW(), INTERVAL 4 DAY) + INTERVAL 16 HOUR, DATE_SUB(NOW(), INTERVAL 0 DAY) + INTERVAL 11 HOUR),
